            <button type="button" class="btn btn-dark position-relative"> <h2>Bootstrap Icons</h2>
                <span class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"> Section 6 </span>
            </button>
            <br /><br />
            <p>Our Bootstrap Icons is a comprehensive library featuring over 1,300 customizable icons that integrate easily with your Bootstrap applications. With a clean and modern design, these SVG icons are ideal for various projects and can be easily scaled and styled as provided below, enhancing user interfaces in web development.</p>
            <hr>

            <div class="col-md-12">
                <div class="alert alert-light alert-dismissible fade show">
                    <h2>How to use Bootstrap icons?</h2>
                    <p><strong>Step 1:</strong> Include the following Bootstrap CDN link in the <code>&lt;head&gt;</code> section of you HTML document.</p>
                    <div><code>&lt;link rel="stylesheet" "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"&gt;</code></div>
                    <p><strong>Step 2:</strong> To place icons into your web page use the syntax <code>&lt;i class="bi-*"&gt;&lt;/i&gt;</code> where <code>*</code> represent the class of a particular icon. So, if an icon class is <code>alarm</code> then the icon HTML code would be <code>&lt;i class="bi-alarm"&gt;&lt;/i&gt;</code>, similarly if the icon class is <code>arrow-down</code> the resulting icon HTML code would be <code>&lt;i class="bi-arrow-down"&gt;&lt;/i&gt;</code>, and so on. </p>

                </div>
            </div>

