                                <script>
            $(document).ready(function () {
                $(".list .name i").click(function () {
                    var t = $(this).attr("class");
                    $("#iconCode").find(".attr-value").text(t), $("#iconModal").find(".modal-header i").attr("class", "").addClass(t);
                    var a = t.replace("bi-", "");
                    $("#addonClass").attr("data-clipboard-text", a).text(a), $("#iconCode").attr("data-clipboard-text", '<i class="bi-' + a + '"></i>'), $("#iconModal").modal("show")
                }), $(".list .name").attr("title", "Click icon to see code"), $('[data-toggle="tooltip"]').tooltip({trigger: "hover"})
            });
                                </script>
