                                                    <div class="col">
                                                        <button type="button" class="btn icon-code copy-btn" id="iconCode" data-toggle="tooltip" title="Click to copy" data-clipboard-text="">
                                                            <span class="html-tag">&lt;i <span class="attr-name">class="<span class="attr-value">fa fa-heart</span>"</span>&gt;&lt;/i&gt;</span>
                                                        </button>
