                                <script data-cfasync="false" src="/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/list.js/1.5.0/list.min.js"></script>
                                <script>
            var options = {
                valueNames: ['name', 'alias']
            };

            var userList = new List('icons', options);

            $(".icon-tags a").click(function () {
                var searchString = $(this).attr("data-tag");
                userList.search(searchString);
                $("#searchInput").val("");
                $(this).addClass("selected").siblings("a").removeClass("selected");
            });

            var clipboard = new ClipboardJS('.copy-btn', {
                container: document.getElementById('iconModal')
            });

            clipboard.on("success", function (e) {
                $(".copy-trigger").html("Copied to clipboard...").delay(500).queue(function () {
                    $(this).html("Click Here to Copy HTML"), $(this).dequeue();
                })
            });
            $(document).ready(function () {
                $(document).on("click", ".copy-trigger", function () {
                    $("#iconCode").click();
                });
            });
                                </script>   
                            </body>
                        </html>
